#!/system/bin/sh
#=============================================
#  徐炯内核辅助 — 一键启动 (MT管理器 Root 执行)
#  卡密验证: 徐炯牛逼
#=============================================

APP_PATH="/data/local/tmp/xujiong_kernel"
LOG_FILE="/data/local/tmp/xj_log.txt"
CARD_KEY="徐炯牛逼"

echo "============================================"
echo "  徐炯内核辅助"
echo "============================================"
echo ""

# ---------- 1. 检查 root ----------
if [ "$(id -u)" != "0" ]; then
    echo "[!] 请以 Root 权限执行此脚本"
    echo "    MT管理器: 长按脚本 → 执行 → 勾选Root"
    exit 1
fi
echo "[√] Root 权限 OK"

# ---------- 2. 卡密验证 ----------
echo "============================================"
echo "  请输入卡密:"
echo "============================================"
read -r INPUT_KEY

if [ "$INPUT_KEY" != "$CARD_KEY" ]; then
    echo ""
    echo "[!] 卡密错误! 退出程序"
    echo "    输入: $INPUT_KEY"
    exit 1
fi

echo ""
echo "[√] 卡密验证通过 — 欢迎使用"
echo ""

# ---------- 3. 检查驱动 ----------
if ! lsmod | grep -qE "mem_tool|km_core"; then
    echo "[!] 警告: 驱动未加载"
    echo "    请先刷入对应内核版本的驱动 (.ko)"
    echo "    内核版本: $(uname -r)"
    echo ""
    echo "    继续运行可能失败..."
    echo ""
fi

# ---------- 4. 提取嵌入的主程序 ----------
echo "[-] 正在解压程序..."
BASE64_START=$(awk '/^__BASE64_START__$/{print NR+1; exit}' "$0")
if [ -z "$BASE64_START" ]; then
    echo "[!] 脚本格式错误: 找不到程序数据"
    exit 1
fi

tail -n +$BASE64_START "$0" | base64 -d > "$APP_PATH"
if [ $? -ne 0 ] || [ ! -f "$APP_PATH" ] || [ ! -s "$APP_PATH" ]; then
    echo "[!] 解压失败!"
    exit 1
fi
echo "[√] 解压完成 ($(stat -c%s "$APP_PATH" 2>/dev/null || wc -c < "$APP_PATH") bytes)"

# ---------- 5. 启动 logcat ----------
echo "[$(date)] 程序启动" > "$LOG_FILE"
logcat -c 2>/dev/null
logcat -s AImGui:V touch:V xj_kernel:V AndroidRuntime:E libc:E DEBUG:E \
    >> "$LOG_FILE" 2>&1 &
LOGCAT_PID=$!
echo "[√] 日志记录 PID=$LOGCAT_PID"

# ---------- 6. 运行主程序 ----------
echo "[-] 启动辅助..."
echo "============================================"
echo ""
chmod 755 "$APP_PATH"
"$APP_PATH" >> "$LOG_FILE" 2>&1
EXIT_CODE=$?

echo "" >> "$LOG_FILE"
echo "============================================" >> "$LOG_FILE"
echo "  程序退出 (exit=$EXIT_CODE)" >> "$LOG_FILE"
echo "============================================" >> "$LOG_FILE"

# ---------- 7. 收尾 ----------
kill $LOGCAT_PID 2>/dev/null

echo ""
echo "============================================"
echo "  程序已退出 (exit=$EXIT_CODE)"
echo "  日志: $LOG_FILE"
echo "============================================"

exit 0
__BASE64_START__
